/* CSK item art: shield / supply-crate / medkit / ammo pickups. Loaded after login by boot-gate.js; until then game.js draws its built-in vector versions. */
window.__GFXD={"shield":"data:image/webp;base64,","crate":"data:image/webp;base64,","med":"data:image/webp;base64,","ammo":"data:image/webp;base64,"};window.GFX=(function(){const o=window.GFX||{},d=window.__GFXD;for(const k in d){const i=new Image();i.onload=function(){try{const c=document.createElement('canvas');c.width=i.naturalWidth;c.height=i.naturalHeight;c.getContext('2d').drawImage(i,0,0);o[k]=c}catch(e){o[k]=i}};i.src=d[k]}return o})();
